// Classification of responses generated by ordinary page activity. This module
// never generates signatures, solves challenges, or replays an API request.
export function appealSummary(payload){
 let redirect=String(payload?.redirect_url||'');try{redirect=decodeURIComponent(redirect);}catch{}
 let url;try{url=new URL(redirect,'https://www.zhihu.com');}catch{}
 const message=url?.searchParams.get('message')||'';
 return {blockLevel:typeof payload?.block_level==='number'?payload.block_level:null,ipRestricted:url?.searchParams.get('type')==='abuseip'||/IP.*异常流量|IP.*限制/i.test(message),requiresLogin:/登录后.*访问|请.*登录/.test(message)};
}
export function accessIssue({url='',text='',httpStatus=null,appeal=null}={}){
 let parsed;try{parsed=new URL(url);}catch{}
 const needsLogin=parsed?.searchParams.get('need_login')==='true'||/请您登录后查看更多|登录后才能继续访问/.test(text)||appeal?.requiresLogin;
 if(needsLogin&&appeal?.ipRestricted)return {code:'LOGIN_REQUIRED_IP_RESTRICTED',message:'平台提示出口IP存在异常流量，并要求先登录；请在本节点浏览器中人工登录后核验搜索权限'};
 if(needsLogin||parsed?.pathname==='/signin')return {code:'LOGIN_REQUIRED',message:'本节点尚未取得可访问搜索页的登录会话，请人工登录后核验'};
 if(appeal?.ipRestricted)return {code:'RISK_CONTROLLED_IP',message:'平台提示出口IP存在异常流量，请暂停该节点并通过平台正常流程处理'};
 if(/请求过于频繁|操作频繁|访问受限|安全验证|异常请求|访问异常|网络环境存在风险|验证后继续|完成验证/.test(text)||/captcha|unhuman/.test(parsed?.pathname||''))return {code:'RISK_CONTROLLED',message:'知乎要求人工安全验证，请暂停采集并在本节点浏览器中处理'};
 if([401,403,429].includes(httpStatus))return {code:httpStatus===401?'LOGIN_REQUIRED':'RISK_CONTROLLED',message:'HTTP '+httpStatus+'；尚无充分证据判断具体触发原因，禁止自动重试'};
 return null;
}
